import React, { useEffect, useState } from "react";
import "./NewsFeeds.scss";
import Marquee from "react-fast-marquee";
import InputBox, { InputTypes } from "../../components/input-box/InputBox";
import { newsCategories } from "../../utils/news";

interface NewsItem {
  id: number;
  title: string;
  content: string; // HTML content
  category: string;
}

const mockNews: NewsItem[] = [
  {
    id: 1,
    title: "ಪೊಸಳ್ಳಿಯಲ್ಲಿ ಅದ್ದೂರಿ ಕೃಷ್ಣ ಕೃಷ್ಣ ಶ್ರೀ ಕೃಷ್ಣಾ - ಸೀಸನ್ ೩",
    content: `<h1>ಪೊಸಳ್ಳಿಯಲ್ಲಿ ಅದ್ದೂರಿ ಕೃಷ್ಣ ಕೃಷ್ಣ ಶ್ರೀ ಕೃಷ್ಣಾ - ಸೀಸನ್ ೩</h1><p><img src="data:image/jpeg;base64,"></p><p>ಬಿ.ಸಿ.ರೋಡ್ : ಬಂಟ್ವಾಳ ತಾಲೂಕು ಕುಲಾಲ ಸುಧಾರಕ ಸಂಘ ಇದರ ಆಶ್ರಯದಲ್ಲಿರುವ ಕುಲಾಲ ಸೇವಾದಳದ ವತಿಯಿಂದ ಕೃಷ್ಣ ಕೃಷ್ಣ ಶ್ರೀ ಕೃಷ್ಣಾ - ಸೀಸನ್ ೩ ಆದಿತ್ಯವಾರ ಬಿ.ಸಿ.ರೋಡಿನ ಪೊಸಳ್ಳಿ ಕುಲಾಲ ಸಮುದಾಯ ಭವನದಲ್ಲಿ ನಡೆಯಿತು. ಬೆಳಿಗ್ಗೆ ನಾರಾಯಣ ಗುರು ವೃತ್ತದ ಬಳಿಯಿಂದ ಕೃಷ್ಣ ವೇಷದಲ್ಲಿರುವ ಪುಟಾಣಿ ಮಕ್ಕಳೊಂದಿಗೆ ಹಿರಿಯ ಶಿಕ್ಷಕ ಚೆನ್ನಕೇಶವ ಮತ್ತು ನವೀನ್ ಬಡ್ಡಕಟ್ಟೆ ಪಾಂಚಜನ್ಯ ಮೊಳಗುವ ಮೂಲಕ ಮೆರವಣೆಗೆಗೆ ಚಾಲನೆ ನೀಡಿದರು. ಮೆರವಣಿಗೆಯಲ್ಲಿ ಗೋವಿನೊಂದಿಗೆ ಗೋಪಾಲಕೃಷ್ಣ, ಮುದ್ದು ಕೃಷ್ಣ, ಬಾಲಕೃಷ್ಣ, ಯಶೋಧ ಕೃಷ್ಣ, ರಾಧಾಕೃಷ್ಣ,  ವೇಷಧಾರಿಗಳೊಂದಿಗೆ ವಾಸುದೇವ ಆದಿಶೇಷನೊಂದಿಗೆ ಆಗಮನ ಹಾಗೂ ಗೋಪಿಕಾಸ್ತ್ರೀ ವೇಷಭೂಷಣ ಆಕರ್ಷಣೀಯವಾಗಿತ್ತು. ಮೆರವಣಿಗೆಯ ಕೊನೆಗೆ ಸಮುದಾಯ ಭವನದಲ್ಲಿ ಮಹಿಳಾ ಘಟಕದ ಸದಸ್ಯೆಯರು ಎಲ್ಲಾ ಕೃಷ್ಣ ವೇಷಧಾರಿಗಳಿಗೆ ಆರತಿ ಎತ್ತಿ ಹಣೆಗೆ ತಿಲಕ ಇಟ್ಟರು.</p><p><img src="data:image/jpeg;base64,"></p><p>ಸಭಾಂಗಣದ ಹೊರಾಂಗಣದಲ್ಲಿ ನಿರ್ಮಿಸಿದ ಗೋವರ್ಧನಗಿರಿಯಡಿಯಲ್ಲಿ ಅಧ್ಯಕ್ಷ ರಮೇಶ್ ಸಾಲ್ಯಾನ್ ಸಂಚಯಗಿರಿ ಕರುವಿಗೆ ಆಹಾರ ನೀಡುವ ಮೂಲಕ ಕಾರ್ಯಕ್ರಮ ಉದ್ಘಾಟಿಸಿದರು. ಇದೇ ಸಂದರ್ಭ ಕಟ್ಟಡ ಸಮಿತಿಯ ಕಾರ್ಯಾಧ್ಯಕ್ಷ ನಾರಾಯಣ ಸಿ. ಪೆರ್ನೆ, ಮಹಿಳಾ ಘಟಕದ ಆಧ್ಯಕ್ಷೆ ಆಶಾಗಿರಿಧರ ಕುಲಾಲ ಮಠ, ಪ್ರಧಾನ ಕಾರ್ಯದರ್ಶಿ ಯಾದವ ಅಗ್ರಬೈಲು, ಕೋಶಾಧಿಕಾರಿ ಸೋಮನಾಥ ಸಾಲ್ಯಾನ್, ಉಪಾಧ್ಯಕ್ಷೆ ಜಲಜಾಕ್ಷಿ ಪಾಣೆಮಂಗಳೂರು, ದಳಪತಿ ಜಯಂತ ಅಗ್ರಬೈಲು, ಕಾಯದರ್ಶಿ ರಾಜೇಶ್ ಭಂಡಾರಿಬೆಟ್ಟು ಉಪಸ್ಥಿತರಿದ್ದರು. ವೈಷ್ಣವಿ ವೈ.ಕೆ. ಅತಿಥಿಗಳನ್ನು ಸ್ವಾಗತಿಸಿದರು. ಸೇವಾದಳದ ಸದಸ್ಯೆ ಸುಕನ್ಯ ಸೌತೆಬಳ್ಳಿ ಕಾರ್ಯಕ್ರಮ ನಿರೂಪಿಸಿದರು. ಉದ್ಘಾಟನೆಯ ನಂತರ ಮುಖ್ಯ ವೇದಿಕೆಯಲ್ಲಿ ವಿವಿಧ ವಿಭಾಗದಲ್ಲಿ ಕೃಷ್ಣ ವೇಷ ಸ್ಪರ್ಧೆ ನಡೆಯಿತು. ಕಿಶೋರ್ ಕೈಕುಂಜೆ, ತಾರನಾಥ ಮೊಡಂಕಾಪು ಕಾರ್ಯಕ್ರಮ ನಿರೂಪಿಸಿದರು.</p>`,
    category: "ಸಂಸ್ಕೃತಿ",
  },
];

const NewsFeeds: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedCategory, setSelectedCategory] = useState("All");
  const [currentPage, setCurrentPage] = useState(1);
  const [filteredNews, setFilteredNews] = useState<NewsItem[]>([]);
  const [mainNews, setMainNews] = useState<NewsItem | null>(null);

  const ITEMS_PER_PAGE = 5;

  useEffect(() => {
    let data = mockNews;

    if (selectedCategory !== "All") {
      data = data.filter((n) => n.category === selectedCategory);
    }

    if (searchTerm.trim()) {
      data = data.filter((n) =>
        n.title.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    setFilteredNews(data);
    setMainNews(data[0] || null);
    setCurrentPage(1);
  }, [searchTerm, selectedCategory]);

  const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
  const paginatedNews = filteredNews.slice(
    startIndex,
    startIndex + ITEMS_PER_PAGE
  );
  const totalPages = Math.ceil(filteredNews.length / ITEMS_PER_PAGE);

  return (
    <div className="news-feed">
      <div className="marquee">
        <Marquee gradient={false} speed={60}>
          {mockNews.map((news) => news.title).join(" | ")}
        </Marquee>
      </div>
      <div className="content-area">
        <div className="main-news">
          {mainNews ? (
            <>
              <div
                className="main-content"
                dangerouslySetInnerHTML={{ __html: mainNews.content }}
              />
              <div className="date-time">
                {new Date()
                  .toLocaleDateString("en-GB", {
                    day: "2-digit",
                    month: "long",
                    year: "numeric",
                  })
                  .replace(/(\d{2}) ([A-Za-z]+) (\d{4})/, "$1 $2, $3")}
              </div>
            </>
          ) : (
            <p>No news available</p>
          )}
        </div>

        <div className="side-news">
          <div className="top-bar">
            <InputBox
              id="search-input"
              name="search-input"
              type={InputTypes.Text}
              label="Search News"
              value={searchTerm}
              isRequired
              setInputValue={(value) => setSearchTerm(value)}
            />

            <div className="filters">
              {newsCategories.map((cat) => (
                <button
                  key={cat}
                  className={`filter-pill ${
                    selectedCategory === cat ? "active" : ""
                  }`}
                  onClick={() => setSelectedCategory(cat)}
                >
                  {cat}
                </button>
              ))}
            </div>
          </div>

          <div className="side-list">
            {paginatedNews.map((news) => (
              <div
                key={news.id}
                className="side-item"
                onClick={() => setMainNews(news)}
              >
                {(() => {
                  const match = news.content.match(
                    /<img[^>]+src=["']([^"']+)["']/i
                  );
                  const imgSrc = match
                    ? match[1]
                    : "https://placehold.co/400x250";
                  return <img src={imgSrc} alt={news.title} />;
                })()}
                <div className="side-text">
                  <h4>{news.title}</h4>
                  <div
                    className="side-content"
                    dangerouslySetInnerHTML={{
                      __html: (() => {
                        // Remove everything before and including the first image tag
                        const imgRegex = /<img[^>]*>[\s\n]*/i;
                        const parts = news.content.split(imgRegex);
                        // parts[1] will be the content after the first image
                        return parts[1] || "";
                      })(),
                    }}
                  />
                </div>
              </div>
            ))}
          </div>

          {totalPages > 1 && (
            <div className="pagination">
              <button
                disabled={currentPage === 1}
                onClick={() => setCurrentPage((p) => p - 1)}
              >
                Prev
              </button>
              <span>
                {currentPage} / {totalPages}
              </span>
              <button
                disabled={currentPage === totalPages}
                onClick={() => setCurrentPage((p) => p + 1)}
              >
                Next
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default NewsFeeds;
